function digestAssetsSetup() {
  var out = { ok: true, files: {} };
  var folderName = 'OC_DigestAssets';
  var it = DriveApp.getFoldersByName(folderName);
  var folder = it.hasNext() ? it.next() : DriveApp.createFolder(folderName);
  var props = PropertiesService.getScriptProperties();
  var assets = [
    { nome: 'ocs-logo.png', b64: OC_DIGEST_ASSET_LOGO_B64, prop: 'OC_DIGEST_LOGO_URL' },
    { nome: 'ocs-masthead.png', b64: OC_DIGEST_ASSET_MASTHEAD_B64, prop: 'OC_DIGEST_MASTHEAD_URL' }
  ];
  assets.forEach(function (a) {
    // idempotente: se il file esiste gia' nella cartella lo sostituisce
    var old = folder.getFilesByName(a.nome);
    while (old.hasNext()) { old.next().setTrashed(true); }
    var blob = Utilities.newBlob(Utilities.base64Decode(a.b64), 'image/png', a.nome);
    var file = folder.createFile(blob);
    try { file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW); } catch (_) {}
    var url = 'https://drive.google.com/thumbnail?id=' + file.getId() + '&sz=w600';
    props.setProperty(a.prop, url);
    out.files[a.nome] = url;
  });
  return out;
}

/** URL degli asset digest dalle ScriptProperties (null se setup non eseguito). */
function _digestAssetUrls_() {
  var p = PropertiesService.getScriptProperties();
  return {
    logo: p.getProperty('OC_DIGEST_LOGO_URL') || null,
    masthead: p.getProperty('OC_DIGEST_MASTHEAD_URL') || null
  };
}
